mapper.select:
SELECT COUNT(*)
  FROM TB_AR01M01 A
     , TB_AR01D01 B
 WHERE A.SHIP_YN = 'N'
   AND A.SHIP_SEQ = B.SHIP_SEQ

   AND A.CO_CD = #{coCd3}


   AND A.TAXIVC_COPRT = #{taxivcCoprt3}


   AND B.PRDT_CD IN (SELECT DISTINCT PRDT_CD
				     FROM TB_BM01M01
				     WHERE PRDT_GRP = #{prdtGrp3}
				     )

SELECT A.CO_CD , TO_CHAR(TO_DATE(A.REQ_DT, 'YYYYMMDD'), 'YYYY-MM-DD') REQ_DT , A.CLNT_CD , (SELECT CLNT_NM FROM TB_BM02M01 WHERE CLNT_CD = A.CLNT_CD) CLNT_NM , A.SHIP_SEQ , (SELECT PRJCT_NM FROM TB_SD05M01 WHERE PRJCT_CD = A.PRJCT_CD) AS PRJCT_NM , A.PRJCT_CD , A.SITE_CD , (SELECT SITE_NM FROM TB_SD09M01 WHERE SITE_CD = A.SITE_CD) AS SITE_NM , A.WH_CD , FN_CM05M01_CD_TO_NM(A.WH_CD) WH_NM , A.TYP_CD , A.OWNER_CD , A.SALES_AREA_CD , A.MNG_TEL , A.DLVR_DTTM , A.DIRTRS_YN , A.DLVR_RMK , A.ADDR_ZIP , A.ADDR_MAIN , A.ADDR_SUB , A.SHIP_RMK , SUM(B.SHIP_QTY) SHIP_TOT_QTY , A.SHIP_TOT_WT , A.SHIP_TOT_AMT , SUM(DECODE(B.SHIP_YN , 'N', B.REAL_SHIP_QTY)) REAL_TOT_QTY , SUM(B.SHIP_QTY) - SUM(DECODE(B.SHIP_YN , 'N', B.REAL_SHIP_QTY)) REMAIN_QTY , A.REAL_TOT_WT , A.REAL_TOT_AMT , A.TRANS_AMT , A.ODR_SEQ , A.ORDRG_SEQ , A.SALES_MNG , A.RECPT_YN , A.SHIP_YN , A.SHIP_PROC_ID , A.SHIP_DTTM , A.ODR_CREAT_DIV FROM TB_AR01M01 A , TB_AR01D01 B WHERE A.SHIP_YN = 'N' AND A.SHIP_SEQ = B.SHIP_SEQ
AND A.CO_CD = #{coCd3}
AND A.TAXIVC_COPRT = #{taxivcCoprt3}
AND B.PRDT_CD IN (SELECT DISTINCT PRDT_CD FROM TB_BM01M01 WHERE PRDT_GRP = #{prdtGrp3} )
GROUP BY A.CO_CD , A.REQ_DT , A.CLNT_CD , A.SHIP_SEQ , A.PRJCT_CD , A.SITE_CD , A.WH_CD , A.TYP_CD , A.OWNER_CD , A.SALES_AREA_CD , A.MNG_TEL , A.DLVR_DTTM , A.DIRTRS_YN , A.DLVR_RMK , A.ADDR_ZIP , A.ADDR_MAIN , A.ADDR_SUB , A.SHIP_RMK , A.SHIP_TOT_QTY , A.SHIP_TOT_WT , A.SHIP_TOT_AMT , A.REAL_TOT_QTY , A.REAL_TOT_WT , A.REAL_TOT_AMT , A.TRANS_AMT , A.ODR_SEQ , A.ORDRG_SEQ , A.SALES_MNG , A.RECPT_YN , A.SHIP_YN , A.SHIP_PROC_ID , A.SHIP_DTTM , A.ODR_CREAT_DIV ORDER BY A.REQ_DT, A.SHIP_SEQ

SELECT COUNT(*)
	  FROM TB_OD01M01 A
    	 , TB_OD01D01 B
 WHERE A.ORDRG_SEQ = B.ORDRG_SEQ
   AND A.ORDRG_YN = 'N'

   AND A.CO_CD = #{coCd2}


   AND B.PRDT_DIV IN (SELECT DISTINCT PRDT_DIV
				     FROM TB_BM01M01
				     WHERE PRDT_GRP = #{prdtGrp2}
				     )


   AND A.TAXIVC_COPRT = #{taxivcCoprt2}

SELECT A.CO_CD , TO_CHAR(TO_DATE(A.REQ_DT, 'YYYYMMDD'), 'YYYY-MM-DD') REQ_DT , (SELECT CLNT_NM FROM TB_BM02M01 WHERE CLNT_CD = A.CLNT_CD) CLNT_NM , A.CLNT_CD , A.ORDRG_SEQ , (SELECT PRJCT_NM FROM TB_SD05M01 WHERE PRJCT_CD = A.PRJCT_CD) AS PRJCT_NM , A.PRJCT_CD , A.SITE_CD , (SELECT SITE_NM FROM TB_SD09M01 WHERE SITE_CD = A.SITE_CD) AS SITE_NM , A.MAKR_CD , FN_CM05M01_CD_TO_NM(A.WH_CD) WH_NM , A.WH_CD , A.TYP_CD , A.OWNER_CD , A.IMP_YN , A.SALES_AREA_CD , A.SELL_CLNT_CD , A.MNG_TEL , A.DLVR_DTTM , A.DLVR_RMK , A.DIRTRS_YN , A.ADDR_ZIP , A.ADDR_MAIN , A.ADDR_SUB , A.ORDRG_RMK , A.TOT_QTY , A.TOT_WT , A.TOT_AMT , A.TRANS_AMT , A.ODR_SEQ , A.PCHS_NO , A.SALES_MNG , A.ORDRG_YN , A.ORDRG_PROC_ID , A.ORDRG_PROC_DTTM , A.ODR_CREAT_DIV , SUM(B.ORDRG_QTY) ORDRG_QTY , SUM(DECODE(B.ORDRG_YN, 'N', B.REAL_DLVR_QTY)) REAL_DLVR_QTY , SUM(B.ORDRG_QTY) - SUM(DECODE(B.ORDRG_YN, 'N', B.REAL_DLVR_QTY)) REMAIN_QTY FROM TB_OD01M01 A , TB_OD01D01 B WHERE A.ORDRG_SEQ = B.ORDRG_SEQ AND A.ORDRG_YN = 'N'
AND A.CO_CD = #{coCd2}
AND B.PRDT_DIV IN (SELECT DISTINCT PRDT_DIV FROM TB_BM01M01 WHERE PRDT_GRP = #{prdtGrp2} )
AND A.TAXIVC_COPRT = #{taxivcCoprt2}
GROUP BY A.CO_CD , A.REQ_DT , A.CLNT_CD , A.ORDRG_SEQ , A.PRJCT_CD , A.SITE_CD , A.MAKR_CD , A.WH_CD , A.TYP_CD , A.OWNER_CD , A.IMP_YN , A.SALES_AREA_CD , A.SELL_CLNT_CD , A.MNG_TEL , A.DLVR_DTTM , A.DLVR_RMK , A.DIRTRS_YN , A.ADDR_ZIP , A.ADDR_MAIN , A.ADDR_SUB , A.ORDRG_RMK , A.TOT_QTY , A.TOT_WT , A.TOT_AMT , A.TRANS_AMT , A.ODR_SEQ , A.PCHS_NO , A.SALES_MNG , A.ORDRG_YN , A.ORDRG_PROC_ID , A.ORDRG_PROC_DTTM , A.ODR_CREAT_DIV ORDER BY REQ_DT, ORDRG_SEQ

SELECT COUNT(*)
  FROM TB_OD02M01 A
     , TB_OD02D01 B
 WHERE A.REQ_SEQ = B.REQ_SEQ
   AND A.ORDRG_YN = 'N'

 AND A.CO_CD = #{coCd1}


 AND B.PRDT_DIV IN (SELECT DISTINCT PRDT_DIV
				    FROM TB_BM01M01
				    WHERE PRDT_GRP = #{prdtGrp1}
				    )

SELECT COUNT(*) FROM TB_AR04M01 A WHERE A.SELPCH_CD = 'SELPCH2'
AND A.CO_CD = #{coCd}
AND DECODE(CSEQ_RCV_YN, 'E', 'N', DECODE(A.SND_YN, 'Y', A.SND_YN, 'N', DECODE(A.CSEQ_RCV_YN, 'Y', A.CSEQ_RCV_YN, 'N', 'N', NULL, 'N'), NULL, DECODE(A.CSEQ_RCV_YN, 'Y', A.CSEQ_RCV_YN, 'N', 'N', NULL, 'N'))) = 'N'

WITH SALES_LIST AS ( SELECT D.CO_CD , D.ORDRS_NO , D.SALES_CD , D.EQP_NM FROM TB_CR02D02 D WHERE D.ORDRS_NO = #{ordrsNo}
AND D.CO_CD = #{coCd}
AND D.SALES_CD = #{salesCd}
AND D.SALES_CD IS NOT NULL ), WBS_SJ AS ( SELECT CO_CD , SALES_CD , SJ_NO , SJ_NM , VER_NO , BEGIN_DT , DE_DT , ACPTNC_DT , END_YN FROM ( SELECT X.CO_CD , X.SALES_CD , X.SJ_NO , X.SJ_NM , X.VER_NO , TO_CHAR(X.BEGIN_DT, 'YYYY-MM-DD') AS BEGIN_DT , TO_CHAR(X.DE_DT, 'YYYY-MM-DD') AS DE_DT , TO_CHAR(X.ACPTNC_DT, 'YYYY-MM-DD') AS ACPTNC_DT , NVL(X.END_YN, 'N') AS END_YN , ROW_NUMBER() OVER ( PARTITION BY X.CO_CD, X.SALES_CD ORDER BY LPAD(NVL(X.VER_NO, '0'), 10, '0') DESC ) AS RN FROM TB_WB21M01 X JOIN SALES_LIST S ON S.CO_CD = X.CO_CD AND S.SALES_CD = X.SALES_CD ) WHERE RN = 1 ), WBS_PLAN_AGG AS ( SELECT W.CO_CD , W.SALES_CD , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE01' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE01_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE01' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE01_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE02' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE02_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE02' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE02_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE03' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE03_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE03' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE03_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE17' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE17_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE17' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE17_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE04' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE04_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE04' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE04_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE05' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE05_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE05' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE05_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE06' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE06_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE06' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE06_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE07' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE07_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE07' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE07_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE08' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE08_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE08' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE08_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE16' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE16_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE16' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE16_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE09' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE09_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE09' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE09_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE10' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE10_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE10' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE10_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE11' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE11_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE11' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE11_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE12' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE12_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE12' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE12_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE13' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE13_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE13' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE13_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE14' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE14_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE14' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE14_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE18' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE18_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE18' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE18_P_CLOSE FROM TB_WB22M01 W JOIN SALES_LIST S ON S.CO_CD = W.CO_CD AND S.SALES_CD = W.SALES_CD WHERE W.WBS_PLAN_CODE_KIND = 'WBSCODE' GROUP BY W.CO_CD, W.SALES_CD ), WBS_RSLT_AGG AS ( SELECT WR.CO_CD , WR.SALES_CD , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE01' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE01_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE01' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE01_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE02' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE02_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE02' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE02_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE03' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE03_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE03' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE03_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE17' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE17_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE17' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE17_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE04', 'WBSCODE05') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE04_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE04', 'WBSCODE05') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE04_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE05', 'WBSCODE07') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE05_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE05', 'WBSCODE07') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE05_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE06', 'WBSCODE08') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE06_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE06', 'WBSCODE08') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE06_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE07', 'WBSCODE09') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE07_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE07', 'WBSCODE09') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE07_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE08' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE08_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE08' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE08_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE16', 'WBSCODE10') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE16_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE16', 'WBSCODE10') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE16_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE09', 'WBSCODE11') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE09_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE09', 'WBSCODE11') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE09_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE10', 'WBSCODE12') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE10_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE10', 'WBSCODE12') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE10_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE11', 'WBSCODE13') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE11_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE11', 'WBSCODE13') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE11_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE12', 'WBSCODE14') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE12_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE12', 'WBSCODE14') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE12_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE13', 'WBSCODE15') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE13_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE13', 'WBSCODE15') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE13_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE14', 'WBSCODE16') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE14_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE14', 'WBSCODE16') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE14_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE18' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE18_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE18' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE18_C FROM TB_WB23M01 WR JOIN SALES_LIST S ON S.CO_CD = WR.CO_CD AND S.SALES_CD = WR.SALES_CD GROUP BY WR.CO_CD, WR.SALES_CD ) SELECT S.CO_CD , S.ORDRS_NO , S.SALES_CD , S.EQP_NM , J.SJ_NO , NVL(J.SJ_NM, S.EQP_NM) AS SJ_NM , J.BEGIN_DT , J.DE_DT , J.ACPTNC_DT , NVL(J.END_YN, 'N') AS END_YN -- 계획 종료일 (P) , P.WBSCODE01_E AS WBSCODE01_P, NVL(P.WBSCODE01_P_CLOSE, 'N') AS WBSCODE01_P_CLOSE , P.WBSCODE02_E AS WBSCODE02_P, NVL(P.WBSCODE02_P_CLOSE, 'N') AS WBSCODE02_P_CLOSE , P.WBSCODE03_E AS WBSCODE03_P, NVL(P.WBSCODE03_P_CLOSE, 'N') AS WBSCODE03_P_CLOSE , P.WBSCODE17_E AS WBSCODE17_P, NVL(P.WBSCODE17_P_CLOSE, 'N') AS WBSCODE17_P_CLOSE , P.WBSCODE04_E AS WBSCODE04_P, NVL(P.WBSCODE04_P_CLOSE, 'N') AS WBSCODE04_P_CLOSE , P.WBSCODE05_E AS WBSCODE05_P, NVL(P.WBSCODE05_P_CLOSE, 'N') AS WBSCODE05_P_CLOSE , P.WBSCODE06_E AS WBSCODE06_P, NVL(P.WBSCODE06_P_CLOSE, 'N') AS WBSCODE06_P_CLOSE , P.WBSCODE07_E AS WBSCODE07_P, NVL(P.WBSCODE07_P_CLOSE, 'N') AS WBSCODE07_P_CLOSE , P.WBSCODE08_E AS WBSCODE08_P, NVL(P.WBSCODE08_P_CLOSE, 'N') AS WBSCODE08_P_CLOSE , P.WBSCODE16_E AS WBSCODE16_P, NVL(P.WBSCODE16_P_CLOSE, 'N') AS WBSCODE16_P_CLOSE , P.WBSCODE09_E AS WBSCODE09_P, NVL(P.WBSCODE09_P_CLOSE, 'N') AS WBSCODE09_P_CLOSE , P.WBSCODE10_E AS WBSCODE10_P, NVL(P.WBSCODE10_P_CLOSE, 'N') AS WBSCODE10_P_CLOSE , P.WBSCODE11_E AS WBSCODE11_P, NVL(P.WBSCODE11_P_CLOSE, 'N') AS WBSCODE11_P_CLOSE , P.WBSCODE12_E AS WBSCODE12_P, NVL(P.WBSCODE12_P_CLOSE, 'N') AS WBSCODE12_P_CLOSE , P.WBSCODE13_E AS WBSCODE13_P, NVL(P.WBSCODE13_P_CLOSE, 'N') AS WBSCODE13_P_CLOSE , P.WBSCODE14_E AS WBSCODE14_P, NVL(P.WBSCODE14_P_CLOSE, 'N') AS WBSCODE14_P_CLOSE , P.WBSCODE18_E AS WBSCODE18_P, NVL(P.WBSCODE18_P_CLOSE, 'N') AS WBSCODE18_P_CLOSE -- 실적 종료일 및 완료여부 (R, C) , R.WBSCODE01_R, NVL(R.WBSCODE01_C, 'N') AS WBSCODE01_C , R.WBSCODE02_R, NVL(R.WBSCODE02_C, 'N') AS WBSCODE02_C , R.WBSCODE03_R, NVL(R.WBSCODE03_C, 'N') AS WBSCODE03_C , R.WBSCODE17_R, NVL(R.WBSCODE17_C, 'N') AS WBSCODE17_C , R.WBSCODE04_R, NVL(R.WBSCODE04_C, 'N') AS WBSCODE04_C , R.WBSCODE05_R, NVL(R.WBSCODE05_C, 'N') AS WBSCODE05_C , R.WBSCODE06_R, NVL(R.WBSCODE06_C, 'N') AS WBSCODE06_C , R.WBSCODE07_R, NVL(R.WBSCODE07_C, 'N') AS WBSCODE07_C , R.WBSCODE08_R, NVL(R.WBSCODE08_C, 'N') AS WBSCODE08_C , R.WBSCODE16_R, NVL(R.WBSCODE16_C, 'N') AS WBSCODE16_C , R.WBSCODE09_R, NVL(R.WBSCODE09_C, 'N') AS WBSCODE09_C , R.WBSCODE10_R, NVL(R.WBSCODE10_C, 'N') AS WBSCODE10_C , R.WBSCODE11_R, NVL(R.WBSCODE11_C, 'N') AS WBSCODE11_C , R.WBSCODE12_R, NVL(R.WBSCODE12_C, 'N') AS WBSCODE12_C , R.WBSCODE13_R, NVL(R.WBSCODE13_C, 'N') AS WBSCODE13_C , R.WBSCODE14_R, NVL(R.WBSCODE14_C, 'N') AS WBSCODE14_C , R.WBSCODE18_R, NVL(R.WBSCODE18_C, 'N') AS WBSCODE18_C FROM SALES_LIST S LEFT OUTER JOIN WBS_SJ J ON J.CO_CD = S.CO_CD AND J.SALES_CD = S.SALES_CD LEFT OUTER JOIN WBS_PLAN_AGG P ON P.CO_CD = S.CO_CD AND P.SALES_CD = S.SALES_CD LEFT OUTER JOIN WBS_RSLT_AGG R ON R.CO_CD = S.CO_CD AND R.SALES_CD = S.SALES_CD ORDER BY S.SALES_CD

SELECT I.CO_CD , I.SALES_CD , D.ORDRS_NO , D.EQP_NM , I.ISS_NO , I.ISS_SJ , I.ISS_CNTS , DECODE(I.REQ_NO, NULL, I.ISS_STS, '', I.ISS_STS, QM.REQ_ST) AS ISS_STS , (SELECT FN_CM05M01_CD_TO_NM(DECODE(I.REQ_NO, NULL, I.ISS_STS, '', I.ISS_STS, QM.REQ_ST)) FROM DUAL) AS ISS_STS_NM , I.ISS_DIV , (SELECT FN_CM05M01_CD_TO_NM(I.ISS_DIV) FROM DUAL) AS ISS_DIV_NM , I.WBS_PLAN_CODE_KIND , (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_KIND = 'WBSCODE' AND CODE_ID = I.WBS_PLAN_CODE_KIND) AS WBS_PLAN_CODE_KIND_NM , I.WBS_PLAN_CODE_ID , (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = I.WBS_PLAN_CODE_ID) AS WBS_PLAN_CODE_ID_NM , I.WBS_PLAN_NO , I.WBS_RSLTS_NO , CASE WHEN I.WBS_RSLTS_NO IS NOT NULL THEN '실적' ELSE '계획' END AS GUBUN , DECODE(I.REQ_NO, NULL, I.ACT_ID, '', I.ACT_ID, QM.ORDRG_ID) AS ACT_ID , (SELECT NAME FROM TB_CM06M01 WHERE ID = DECODE(I.REQ_NO, NULL, I.ACT_ID, '', I.ACT_ID, QM.ORDRG_ID)) AS ACT_NM , I.REQ_NO , QM.REQ_ST , (SELECT FN_CM05M01_CD_TO_NM(QM.REQ_ST) FROM DUAL) AS REQ_ST_NM , QP.RSLT_NO , TO_CHAR(I.CREAT_DTTM, 'YYYY-MM-DD') AS CREAT_DT , TO_CHAR(ACT.ACTE_DT, 'YYYY-MM-DD') AS ACTE_DT , ACT.ACT_CNTS FROM TB_WB24M02 I LEFT OUTER JOIN TB_CR02D02 D ON D.CO_CD = I.CO_CD AND D.SALES_CD = I.SALES_CD LEFT OUTER JOIN TB_WB24M03 ACT ON ACT.ISS_NO = I.ISS_NO LEFT OUTER JOIN TB_QM01M01 QM ON QM.REQ_NO = I.REQ_NO LEFT OUTER JOIN TB_QM01P01 QP ON QP.REQ_NO = I.REQ_NO WHERE 1 = 1
AND I.CO_CD = #{coCd}
AND (D.ORDRS_NO = #{ordrsNo} OR I.SALES_CD LIKE #{ordrsNo} || '%')
AND I.SALES_CD = #{salesCd}
ORDER BY I.SALES_CD, I.WBS_PLAN_CODE_KIND, I.ISS_NO DESC

WITH FILTERED_M AS ( SELECT /*+ MATERIALIZE */ M.CO_CD , M.ORDRS_CLNT_CD , M.ORDRS_NO , M.HIST_NO , M.CTRT_NM , M.CLNT_PJT , M.ORDRS_DT FROM ( SELECT X.CO_CD , X.ORDRS_CLNT_CD , X.ORDRS_NO , X.HIST_NO , X.CTRT_NM , X.CLNT_PJT , X.ORDRS_DT , ROW_NUMBER() OVER ( PARTITION BY X.CO_CD, X.ORDRS_NO ORDER BY LPAD(NVL(TO_CHAR(X.HIST_NO), '0'), 10, '0') DESC ) AS HIST_RN FROM TB_CR02M01 X WHERE X.ORDRS_CLNT_CD IN
#{clntCd}
AND X.CO_CD = #{coCd}
AND X.ORDRS_DT >= TO_DATE(REPLACE(#{strtDt}, '-', ''), 'YYYYMMDD')
AND X.ORDRS_DT < TO_DATE(REPLACE(#{endDt}, '-', ''), 'YYYYMMDD') + 1
) M WHERE M.HIST_RN = 1 ),
,
LATEST_CLNT_HIST AS ( SELECT F.CO_CD , F.ORDRS_CLNT_CD , F.ORDRS_NO , F.HIST_NO , F.CTRT_NM , F.CLNT_PJT , F.ORDRS_DT , ROW_NUMBER() OVER ( PARTITION BY F.CO_CD, F.ORDRS_CLNT_CD ORDER BY NVL(F.ORDRS_DT, TO_DATE('19000101', 'YYYYMMDD')) DESC, F.ORDRS_NO DESC ) AS CLNT_ORD_RN FROM FILTERED_M F
LEFT OUTER JOIN ORDER_END_STAT OE ON OE.CO_CD = F.CO_CD AND OE.ORDRS_NO = F.ORDRS_NO
WHERE 1 = 1
AND NVL(OE.SALES_CNT, 0) > 0 AND OE.ALL_ENDED_YN = 1
AND NVL(OE.ALL_ENDED_YN, 0) = 0
), TARGET_ORDRS AS ( SELECT /*+ MATERIALIZE */ CO_CD , ORDRS_CLNT_CD , ORDRS_NO , HIST_NO , CTRT_NM , CLNT_PJT , ORDRS_DT , CLNT_ORD_RN FROM LATEST_CLNT_HIST WHERE CLNT_ORD_RN <= 15 ), LATEST_CLNT_ORDR AS ( SELECT CO_CD , ORDRS_CLNT_CD , ORDRS_NO AS LATEST_ORDRS_NO , HIST_NO AS LATEST_HIST_NO , CTRT_NM AS LATEST_CTRT_NM , CLNT_PJT AS LATEST_CLNT_PJT , CASE WHEN ORDRS_DT IS NOT NULL THEN TO_CHAR(ORDRS_DT, 'YYYY-MM-DD') ELSE '' END AS LATEST_ORDRS_DT FROM TARGET_ORDRS WHERE CLNT_ORD_RN = 1 ), SALES_LIST AS ( SELECT /*+ MATERIALIZE */ T.CO_CD , T.ORDRS_CLNT_CD , T.ORDRS_NO , D.SALES_CD , D.DUDT_INTEND_DT FROM TARGET_ORDRS T JOIN TB_CR02D02 D ON D.CO_CD = T.CO_CD AND D.ORDRS_NO = T.ORDRS_NO WHERE D.SALES_CD IS NOT NULL ), CLNT_ORDRS_META AS ( SELECT CO_CD , ORDRS_CLNT_CD , TO_CHAR(MIN(DUDT_INTEND_DT), 'YYYY-MM-DD') AS MIN_DUDT , TO_CHAR(MAX(DUDT_INTEND_DT), 'YYYY-MM-DD') AS MAX_DUDT FROM SALES_LIST GROUP BY CO_CD, ORDRS_CLNT_CD ), , WBS_CLNT_AGG AS ( SELECT CO_CD , ORDRS_CLNT_CD , COUNT(DISTINCT SALES_CD) AS SALES_CNT , MIN(CASE WHEN END_YN = 'Y' THEN 1 ELSE 0 END) AS ALL_ENDED_YN , SUM(CASE WHEN STEP_TYPE = 'ONGOING_DELAY' THEN 1 ELSE 0 END) AS ONGOING_DELAY_CNT , MAX(ONGOING_DELAY_DAYS) AS WBS_MAX_DELAY_DAYS , SUM(CASE WHEN STEP_TYPE = 'ONGOING_WARN' THEN 1 ELSE 0 END) AS WARN_CNT , SUM(CASE WHEN STEP_TYPE = 'ONGOING_ONTIME' THEN 1 ELSE 0 END) AS ONGOING_ONTIME_CNT , SUM(CASE WHEN STEP_TYPE = 'COMP_DELAY' THEN 1 ELSE 0 END) AS COMP_DELAY_CNT , SUM(CASE WHEN STEP_TYPE = 'COMP_ONTIME' THEN 1 ELSE 0 END) AS COMP_ONTIME_CNT FROM STEP_EVAL GROUP BY CO_CD, ORDRS_CLNT_CD ), WBS_ISS_AGG AS ( SELECT CO_CD , ORDRS_CLNT_CD , COUNT(*) AS ISS_TOT_CNT , SUM(CASE WHEN IS_RESOLVED = 0 THEN 1 ELSE 0 END) AS ISS_UNCOMP_CNT FROM ( SELECT S.CO_CD , S.ORDRS_CLNT_CD , I.ISS_NO , MAX( CASE WHEN DECODE(I.REQ_NO, NULL, I.ISS_STS, '', I.ISS_STS, QM.REQ_ST) IN ('ISSSTS03', 'REQST03') THEN 1 WHEN STS.CODE_NM IN ('조치완료', '완료') THEN 1 WHEN QP.RSLT_NO IS NOT NULL OR ACT.ACTE_DT IS NOT NULL THEN 1 ELSE 0 END ) AS IS_RESOLVED FROM (SELECT DISTINCT CO_CD, ORDRS_CLNT_CD, SALES_CD FROM SALES_LIST) S JOIN TB_WB24M02 I ON I.CO_CD = S.CO_CD AND I.SALES_CD = S.SALES_CD LEFT OUTER JOIN TB_WB24M03 ACT ON ACT.ISS_NO = I.ISS_NO LEFT OUTER JOIN TB_QM01M01 QM ON QM.REQ_NO = I.REQ_NO LEFT OUTER JOIN TB_QM01P01 QP ON QP.REQ_NO = I.REQ_NO LEFT OUTER JOIN TB_CM05M01 STS ON STS.CODE_ID = DECODE(I.REQ_NO, NULL, I.ISS_STS, '', I.ISS_STS, QM.REQ_ST) GROUP BY S.CO_CD, S.ORDRS_CLNT_CD, I.ISS_NO ) GROUP BY CO_CD, ORDRS_CLNT_CD ) SELECT L.CO_CD , L.ORDRS_CLNT_CD , NVL(W.SALES_CNT, 0) AS SALES_CNT , L.LATEST_ORDRS_NO , L.LATEST_HIST_NO , L.LATEST_CTRT_NM , (SELECT D.CODE_NM FROM TB_CM05M01 D WHERE D.CODE_ID = L.LATEST_CLNT_PJT) AS LATEST_CLNT_PJT_NM , L.LATEST_ORDRS_DT , M.MIN_DUDT , M.MAX_DUDT , NVL(W.ONGOING_DELAY_CNT, 0) AS DELAY_STEP_CNT , NVL(W.WARN_CNT, 0) AS WARN_STEP_CNT , CASE WHEN NVL(W.SALES_CNT, 0) = 0 THEN 'NONE' WHEN W.ONGOING_DELAY_CNT > 0 THEN 'ONGOING_DELAY' WHEN W.WARN_CNT > 0 THEN 'ONGOING_WARN' WHEN W.ALL_ENDED_YN = 1 THEN CASE WHEN W.COMP_DELAY_CNT > 0 THEN 'COMP_DELAY' ELSE 'ALL_ENDED' END WHEN W.ONGOING_ONTIME_CNT > 0 THEN 'ONGOING_ONTIME' WHEN W.COMP_DELAY_CNT > 0 THEN 'COMP_DELAY' WHEN W.COMP_ONTIME_CNT > 0 THEN 'COMP_ONTIME' ELSE 'NONE' END AS WBS_STATUS , NVL(W.WBS_MAX_DELAY_DAYS, 0) AS WBS_MAX_DELAY_DAYS , NVL(ISS.ISS_TOT_CNT, 0) AS ISS_TOT_CNT , NVL(ISS.ISS_UNCOMP_CNT, 0) AS ISS_UNCOMP_CNT FROM LATEST_CLNT_ORDR L LEFT OUTER JOIN CLNT_ORDRS_META M ON M.CO_CD = L.CO_CD AND M.ORDRS_CLNT_CD = L.ORDRS_CLNT_CD LEFT OUTER JOIN WBS_CLNT_AGG W ON W.CO_CD = L.CO_CD AND W.ORDRS_CLNT_CD = L.ORDRS_CLNT_CD LEFT OUTER JOIN WBS_ISS_AGG ISS ON ISS.CO_CD = L.CO_CD AND ISS.ORDRS_CLNT_CD = L.ORDRS_CLNT_CD

WITH TARGET_ORDRS AS ( SELECT M.CO_CD , M.ORDRS_CLNT_CD , M.ORDRS_NO , M.HIST_NO , M.CTRT_NM , M.CLNT_PJT , D.CODE_NM AS CLNT_PJT_NM , M.ORDRS_DT , U.NAME AS MNG_NM FROM ( SELECT X.* , ROW_NUMBER() OVER ( PARTITION BY X.CO_CD, X.ORDRS_NO ORDER BY LPAD(NVL(TO_CHAR(X.HIST_NO), '0'), 10, '0') DESC ) AS RN FROM TB_CR02M01 X WHERE X.ORDRS_CLNT_CD = #{ordrsClntCd}
AND X.CO_CD = #{coCd}
AND X.ORDRS_DT >= TO_DATE(REPLACE(#{strtDt}, '-', ''), 'YYYYMMDD')
AND X.ORDRS_DT < TO_DATE(REPLACE(#{endDt}, '-', ''), 'YYYYMMDD') + 1
) M LEFT OUTER JOIN TB_CM05M01 D ON M.CLNT_PJT = D.CODE_ID LEFT OUTER JOIN TB_CM06M01 U ON M.MNG_ID = U.ID WHERE M.RN = 1 ), SALES_LIST AS ( SELECT /*+ MATERIALIZE */ T.CO_CD , T.ORDRS_CLNT_CD , T.ORDRS_NO , D.SALES_CD FROM TARGET_ORDRS T JOIN TB_CR02D02 D ON D.CO_CD = T.CO_CD AND D.ORDRS_NO = T.ORDRS_NO WHERE D.SALES_CD IS NOT NULL ), , WBS_ORDRS_AGG AS ( SELECT CO_CD , ORDRS_NO , COUNT(DISTINCT SALES_CD) AS SALES_CNT , MIN(CASE WHEN END_YN = 'Y' THEN 1 ELSE 0 END) AS ALL_ENDED_YN , SUM(CASE WHEN STEP_TYPE = 'ONGOING_DELAY' THEN 1 ELSE 0 END) AS ONGOING_DELAY_CNT , MAX(ONGOING_DELAY_DAYS) AS WBS_MAX_DELAY_DAYS , SUM(CASE WHEN STEP_TYPE = 'ONGOING_WARN' THEN 1 ELSE 0 END) AS WARN_CNT , SUM(CASE WHEN STEP_TYPE = 'ONGOING_ONTIME' THEN 1 ELSE 0 END) AS ONGOING_ONTIME_CNT , SUM(CASE WHEN STEP_TYPE = 'COMP_DELAY' THEN 1 ELSE 0 END) AS COMP_DELAY_CNT , SUM(CASE WHEN STEP_TYPE = 'COMP_ONTIME' THEN 1 ELSE 0 END) AS COMP_ONTIME_CNT FROM STEP_EVAL GROUP BY CO_CD, ORDRS_NO ), WBS_ISS_AGG AS ( SELECT CO_CD , ORDRS_NO , COUNT(*) AS ISS_TOT_CNT , SUM(CASE WHEN IS_RESOLVED = 0 THEN 1 ELSE 0 END) AS ISS_UNCOMP_CNT FROM ( SELECT S.CO_CD , S.ORDRS_NO , I.ISS_NO , MAX( CASE WHEN DECODE(I.REQ_NO, NULL, I.ISS_STS, '', I.ISS_STS, QM.REQ_ST) IN ('ISSSTS03', 'REQST03') THEN 1 WHEN STS.CODE_NM IN ('조치완료', '완료') THEN 1 WHEN QP.RSLT_NO IS NOT NULL OR ACT.ACTE_DT IS NOT NULL THEN 1 ELSE 0 END ) AS IS_RESOLVED FROM (SELECT DISTINCT CO_CD, ORDRS_NO, SALES_CD FROM SALES_LIST) S JOIN TB_WB24M02 I ON I.CO_CD = S.CO_CD AND I.SALES_CD = S.SALES_CD LEFT OUTER JOIN TB_WB24M03 ACT ON ACT.ISS_NO = I.ISS_NO LEFT OUTER JOIN TB_QM01M01 QM ON QM.REQ_NO = I.REQ_NO LEFT OUTER JOIN TB_QM01P01 QP ON QP.REQ_NO = I.REQ_NO LEFT OUTER JOIN TB_CM05M01 STS ON STS.CODE_ID = DECODE(I.REQ_NO, NULL, I.ISS_STS, '', I.ISS_STS, QM.REQ_ST) GROUP BY S.CO_CD, S.ORDRS_NO, I.ISS_NO ) GROUP BY CO_CD, ORDRS_NO ) SELECT T.CO_CD , T.ORDRS_CLNT_CD , T.ORDRS_NO , T.HIST_NO , T.CTRT_NM , T.CLNT_PJT , T.CLNT_PJT_NM , CASE WHEN T.ORDRS_DT IS NOT NULL THEN TO_CHAR(T.ORDRS_DT, 'YYYY-MM-DD') ELSE '' END AS ORDRS_DT , (SELECT TO_CHAR(MAX(D2.DUDT_INTEND_DT), 'YYYY-MM-DD') FROM TB_CR02D02 D2 WHERE D2.CO_CD = T.CO_CD AND D2.ORDRS_NO = T.ORDRS_NO) AS DUDT , T.MNG_NM , NVL( (SELECT CASE WHEN COUNT(A.TODO_KEY) = 0 THEN 'NONE' WHEN SUM(CASE WHEN NVL(A.APPR_REJECT_YN, 'N') = 'Y' THEN 1 ELSE 0 END) > 0 THEN 'REJECT' WHEN COUNT(A.TODO_KEY) = SUM(DECODE(NVL(A.SANCTN_STTUS, 'N'), 'N', 0, 'Y', 1)) THEN 'COMPLETE' WHEN SUM(DECODE(NVL(A.SANCTN_STTUS, 'N'), 'N', 0, 'Y', 1)) = 0 THEN 'REQUEST' ELSE 'PROGRESS' END FROM TB_WB20M03 A WHERE A.TODO_NO = T.ORDRS_NO AND A.ETC_FIELD2 = T.HIST_NO AND A.TODO_DIV1_CODE_ID = 'TODODIV20'), 'NONE') AS STEP1_APP_STATUS , NVL(W.SALES_CNT, 0) AS SALES_CNT , CASE WHEN NVL(W.SALES_CNT, 0) = 0 THEN 'NONE' WHEN W.ONGOING_DELAY_CNT > 0 THEN 'ONGOING_DELAY' WHEN W.WARN_CNT > 0 THEN 'ONGOING_WARN' WHEN W.ALL_ENDED_YN = 1 THEN CASE WHEN W.COMP_DELAY_CNT > 0 THEN 'COMP_DELAY' ELSE 'ALL_ENDED' END WHEN W.ONGOING_ONTIME_CNT > 0 THEN 'ONGOING_ONTIME' WHEN W.COMP_DELAY_CNT > 0 THEN 'COMP_DELAY' WHEN W.COMP_ONTIME_CNT > 0 THEN 'COMP_ONTIME' ELSE 'NONE' END AS WBS_STATUS , NVL(W.WBS_MAX_DELAY_DAYS, 0) AS WBS_MAX_DELAY_DAYS , NVL(ISS.ISS_TOT_CNT, 0) AS ISS_TOT_CNT , NVL(ISS.ISS_UNCOMP_CNT, 0) AS ISS_UNCOMP_CNT FROM TARGET_ORDRS T LEFT OUTER JOIN WBS_ORDRS_AGG W ON W.CO_CD = T.CO_CD AND W.ORDRS_NO = T.ORDRS_NO LEFT OUTER JOIN WBS_ISS_AGG ISS ON ISS.CO_CD = T.CO_CD AND ISS.ORDRS_NO = T.ORDRS_NO WHERE 1 = 1
AND NVL(W.SALES_CNT, 0) > 0 AND W.ALL_ENDED_YN = 1
AND NVL(W.ALL_ENDED_YN, 0) = 0
ORDER BY T.ORDRS_DT DESC NULLS LAST, T.ORDRS_NO DESC

WITH FILTERED_M AS ( SELECT M.CO_CD , M.ORDRS_NO , M.HIST_NO , M.CTRT_NM FROM ( SELECT X.CO_CD , X.ORDRS_NO , X.HIST_NO , X.CTRT_NM , ROW_NUMBER() OVER ( PARTITION BY X.CO_CD, X.ORDRS_NO ORDER BY LPAD(NVL(TO_CHAR(X.HIST_NO), '0'), 10, '0') DESC ) AS RN FROM TB_CR02M01 X WHERE X.ORDRS_CLNT_CD = #{ordrsClntCd}
AND X.CO_CD = #{coCd}
AND X.ORDRS_NO = #{ordrsNo}
AND X.ORDRS_DT >= TO_DATE(REPLACE(#{strtDt}, '-', ''), 'YYYYMMDD')
AND X.ORDRS_DT < TO_DATE(REPLACE(#{endDt}, '-', ''), 'YYYYMMDD') + 1
) M WHERE M.RN = 1 ),
,
TARGET_ORDRS AS ( SELECT F.CO_CD , F.ORDRS_NO , F.HIST_NO , F.CTRT_NM FROM FILTERED_M F
LEFT OUTER JOIN ORDER_END_STAT OE ON OE.CO_CD = F.CO_CD AND OE.ORDRS_NO = F.ORDRS_NO
WHERE 1 = 1
AND NVL(OE.SALES_CNT, 0) > 0 AND OE.ALL_ENDED_YN = 1
AND NVL(OE.ALL_ENDED_YN, 0) = 0
), SALES_LIST AS ( SELECT D.CO_CD , D.ORDRS_NO , T.HIST_NO , T.CTRT_NM , D.SALES_CD , D.EQP_NM FROM TB_CR02D02 D JOIN TARGET_ORDRS T ON T.CO_CD = D.CO_CD AND T.ORDRS_NO = D.ORDRS_NO WHERE D.SALES_CD IS NOT NULL
AND D.SALES_CD = #{salesCd}
), WBS_SJ AS ( SELECT CO_CD , SALES_CD , SJ_NO , SJ_NM , VER_NO , BEGIN_DT , DE_DT , ACPTNC_DT , END_YN FROM ( SELECT X.CO_CD , X.SALES_CD , X.SJ_NO , X.SJ_NM , X.VER_NO , TO_CHAR(X.BEGIN_DT, 'YYYY-MM-DD') AS BEGIN_DT , TO_CHAR(X.DE_DT, 'YYYY-MM-DD') AS DE_DT , TO_CHAR(X.ACPTNC_DT, 'YYYY-MM-DD') AS ACPTNC_DT , NVL(X.END_YN, 'N') AS END_YN , ROW_NUMBER() OVER ( PARTITION BY X.CO_CD, X.SALES_CD ORDER BY LPAD(NVL(X.VER_NO, '0'), 10, '0') DESC ) AS RN FROM TB_WB21M01 X JOIN (SELECT DISTINCT CO_CD, SALES_CD FROM SALES_LIST) S ON S.CO_CD = X.CO_CD AND S.SALES_CD = X.SALES_CD ) WHERE RN = 1 ), WBS_PLAN_AGG AS ( SELECT W.CO_CD , W.SALES_CD , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE01' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE01_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE01' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE01_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE02' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE02_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE02' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE02_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE03' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE03_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE03' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE03_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE17' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE17_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE17' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE17_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE04' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE04_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE04' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE04_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE05' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE05_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE05' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE05_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE06' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE06_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE06' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE06_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE07' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE07_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE07' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE07_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE08' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE08_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE08' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE08_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE16' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE16_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE16' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE16_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE09' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE09_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE09' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE09_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE10' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE10_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE10' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE10_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE11' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE11_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE11' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE11_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE12' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE12_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE12' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE12_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE13' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE13_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE13' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE13_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE14' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE14_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE14' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE14_P_CLOSE , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE18' AND W.WBS_PLANE_DT IS NOT NULL THEN TO_CHAR(W.WBS_PLANE_DT, 'YYYY-MM-DD') END) AS WBSCODE18_E , MAX(CASE WHEN W.WBS_PLAN_CODE_ID = 'WBSCODE18' AND W.CLOSE_YN = 'Y' THEN 'Y' ELSE 'N' END) AS WBSCODE18_P_CLOSE FROM TB_WB22M01 W JOIN (SELECT DISTINCT CO_CD, SALES_CD FROM SALES_LIST) S ON S.CO_CD = W.CO_CD AND S.SALES_CD = W.SALES_CD WHERE W.WBS_PLAN_CODE_KIND = 'WBSCODE' GROUP BY W.CO_CD, W.SALES_CD ), WBS_RSLT_AGG AS ( SELECT WR.CO_CD , WR.SALES_CD , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE01' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE01_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE01' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE01_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE02' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE02_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE02' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE02_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE03' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE03_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE03' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE03_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE17' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE17_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE17' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE17_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE04', 'WBSCODE05') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE04_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE04', 'WBSCODE05') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE04_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE05', 'WBSCODE07') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE05_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE05', 'WBSCODE07') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE05_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE06', 'WBSCODE08') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE06_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE06', 'WBSCODE08') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE06_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE07', 'WBSCODE09') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE07_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE07', 'WBSCODE09') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE07_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE08' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE08_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE08' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE08_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE16', 'WBSCODE10') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE16_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE16', 'WBSCODE10') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE16_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE09', 'WBSCODE11') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE09_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE09', 'WBSCODE11') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE09_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE10', 'WBSCODE12') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE10_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE10', 'WBSCODE12') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE10_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE11', 'WBSCODE13') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE11_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE11', 'WBSCODE13') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE11_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE12', 'WBSCODE14') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE12_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE12', 'WBSCODE14') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE12_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE13', 'WBSCODE15') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE13_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE13', 'WBSCODE15') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE13_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE14', 'WBSCODE16') AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE14_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND IN ('WBSCODE14', 'WBSCODE16') AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE14_C , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE18' AND WR.WBS_RSLTSE_DT IS NOT NULL THEN TO_CHAR(WR.WBS_RSLTSE_DT, 'YYYY-MM-DD') END) AS WBSCODE18_R , MAX(CASE WHEN WR.WBS_PLAN_CODE_KIND = 'WBSCODE18' AND (WR.CLOSE_YN = 'Y' OR TO_CHAR(WR.WBS_RSLTS_RATE) = '100') THEN 'Y' ELSE 'N' END) AS WBSCODE18_C FROM TB_WB23M01 WR JOIN (SELECT DISTINCT CO_CD, SALES_CD FROM SALES_LIST) S ON S.CO_CD = WR.CO_CD AND S.SALES_CD = WR.SALES_CD GROUP BY WR.CO_CD, WR.SALES_CD ) SELECT S.CO_CD , S.ORDRS_NO , S.HIST_NO , S.CTRT_NM , S.SALES_CD , S.EQP_NM , J.SJ_NO , NVL(J.SJ_NM, S.EQP_NM) AS SJ_NM , J.BEGIN_DT , J.DE_DT , J.ACPTNC_DT , NVL(J.END_YN, 'N') AS END_YN , P.WBSCODE01_E AS WBSCODE01_P, NVL(P.WBSCODE01_P_CLOSE, 'N') AS WBSCODE01_P_CLOSE , P.WBSCODE02_E AS WBSCODE02_P, NVL(P.WBSCODE02_P_CLOSE, 'N') AS WBSCODE02_P_CLOSE , P.WBSCODE03_E AS WBSCODE03_P, NVL(P.WBSCODE03_P_CLOSE, 'N') AS WBSCODE03_P_CLOSE , P.WBSCODE17_E AS WBSCODE17_P, NVL(P.WBSCODE17_P_CLOSE, 'N') AS WBSCODE17_P_CLOSE , P.WBSCODE04_E AS WBSCODE04_P, NVL(P.WBSCODE04_P_CLOSE, 'N') AS WBSCODE04_P_CLOSE , P.WBSCODE05_E AS WBSCODE05_P, NVL(P.WBSCODE05_P_CLOSE, 'N') AS WBSCODE05_P_CLOSE , P.WBSCODE06_E AS WBSCODE06_P, NVL(P.WBSCODE06_P_CLOSE, 'N') AS WBSCODE06_P_CLOSE , P.WBSCODE07_E AS WBSCODE07_P, NVL(P.WBSCODE07_P_CLOSE, 'N') AS WBSCODE07_P_CLOSE , P.WBSCODE08_E AS WBSCODE08_P, NVL(P.WBSCODE08_P_CLOSE, 'N') AS WBSCODE08_P_CLOSE , P.WBSCODE16_E AS WBSCODE16_P, NVL(P.WBSCODE16_P_CLOSE, 'N') AS WBSCODE16_P_CLOSE , P.WBSCODE09_E AS WBSCODE09_P, NVL(P.WBSCODE09_P_CLOSE, 'N') AS WBSCODE09_P_CLOSE , P.WBSCODE10_E AS WBSCODE10_P, NVL(P.WBSCODE10_P_CLOSE, 'N') AS WBSCODE10_P_CLOSE , P.WBSCODE11_E AS WBSCODE11_P, NVL(P.WBSCODE11_P_CLOSE, 'N') AS WBSCODE11_P_CLOSE , P.WBSCODE12_E AS WBSCODE12_P, NVL(P.WBSCODE12_P_CLOSE, 'N') AS WBSCODE12_P_CLOSE , P.WBSCODE13_E AS WBSCODE13_P, NVL(P.WBSCODE13_P_CLOSE, 'N') AS WBSCODE13_P_CLOSE , P.WBSCODE14_E AS WBSCODE14_P, NVL(P.WBSCODE14_P_CLOSE, 'N') AS WBSCODE14_P_CLOSE , P.WBSCODE18_E AS WBSCODE18_P, NVL(P.WBSCODE18_P_CLOSE, 'N') AS WBSCODE18_P_CLOSE , R.WBSCODE01_R, NVL(R.WBSCODE01_C, 'N') AS WBSCODE01_C , R.WBSCODE02_R, NVL(R.WBSCODE02_C, 'N') AS WBSCODE02_C , R.WBSCODE03_R, NVL(R.WBSCODE03_C, 'N') AS WBSCODE03_C , R.WBSCODE17_R, NVL(R.WBSCODE17_C, 'N') AS WBSCODE17_C , R.WBSCODE04_R, NVL(R.WBSCODE04_C, 'N') AS WBSCODE04_C , R.WBSCODE05_R, NVL(R.WBSCODE05_C, 'N') AS WBSCODE05_C , R.WBSCODE06_R, NVL(R.WBSCODE06_C, 'N') AS WBSCODE06_C , R.WBSCODE07_R, NVL(R.WBSCODE07_C, 'N') AS WBSCODE07_C , R.WBSCODE08_R, NVL(R.WBSCODE08_C, 'N') AS WBSCODE08_C , R.WBSCODE16_R, NVL(R.WBSCODE16_C, 'N') AS WBSCODE16_C , R.WBSCODE09_R, NVL(R.WBSCODE09_C, 'N') AS WBSCODE09_C , R.WBSCODE10_R, NVL(R.WBSCODE10_C, 'N') AS WBSCODE10_C , R.WBSCODE11_R, NVL(R.WBSCODE11_C, 'N') AS WBSCODE11_C , R.WBSCODE12_R, NVL(R.WBSCODE12_C, 'N') AS WBSCODE12_C , R.WBSCODE13_R, NVL(R.WBSCODE13_C, 'N') AS WBSCODE13_C , R.WBSCODE14_R, NVL(R.WBSCODE14_C, 'N') AS WBSCODE14_C , R.WBSCODE18_R, NVL(R.WBSCODE18_C, 'N') AS WBSCODE18_C FROM SALES_LIST S LEFT OUTER JOIN WBS_SJ J ON J.CO_CD = S.CO_CD AND J.SALES_CD = S.SALES_CD LEFT OUTER JOIN WBS_PLAN_AGG P ON P.CO_CD = S.CO_CD AND P.SALES_CD = S.SALES_CD LEFT OUTER JOIN WBS_RSLT_AGG R ON R.CO_CD = S.CO_CD AND R.SALES_CD = S.SALES_CD ORDER BY S.ORDRS_NO DESC, S.SALES_CD

WITH FILTERED_M AS ( SELECT M.CO_CD , M.ORDRS_NO , M.CTRT_NM FROM ( SELECT X.CO_CD , X.ORDRS_NO , X.CTRT_NM , ROW_NUMBER() OVER ( PARTITION BY X.CO_CD, X.ORDRS_NO ORDER BY LPAD(NVL(TO_CHAR(X.HIST_NO), '0'), 10, '0') DESC ) AS RN FROM TB_CR02M01 X WHERE X.ORDRS_CLNT_CD = #{ordrsClntCd}
AND X.CO_CD = #{coCd}
AND X.ORDRS_NO = #{ordrsNo}
AND X.ORDRS_DT >= TO_DATE(REPLACE(#{strtDt}, '-', ''), 'YYYYMMDD')
AND X.ORDRS_DT < TO_DATE(REPLACE(#{endDt}, '-', ''), 'YYYYMMDD') + 1
) M WHERE M.RN = 1 ),
,
TARGET_ORDRS AS ( SELECT F.CO_CD , F.ORDRS_NO , F.CTRT_NM FROM FILTERED_M F
LEFT OUTER JOIN ORDER_END_STAT OE ON OE.CO_CD = F.CO_CD AND OE.ORDRS_NO = F.ORDRS_NO
WHERE 1 = 1
AND NVL(OE.SALES_CNT, 0) > 0 AND OE.ALL_ENDED_YN = 1
AND NVL(OE.ALL_ENDED_YN, 0) = 0
) SELECT DISTINCT I.CO_CD , I.SALES_CD , T.ORDRS_NO , T.CTRT_NM , D.EQP_NM , I.ISS_NO , I.ISS_SJ , I.ISS_CNTS , DECODE(I.REQ_NO, NULL, I.ISS_STS, '', I.ISS_STS, QM.REQ_ST) AS ISS_STS , (SELECT FN_CM05M01_CD_TO_NM(DECODE(I.REQ_NO, NULL, I.ISS_STS, '', I.ISS_STS, QM.REQ_ST)) FROM DUAL) AS ISS_STS_NM , I.ISS_DIV , (SELECT FN_CM05M01_CD_TO_NM(I.ISS_DIV) FROM DUAL) AS ISS_DIV_NM , I.WBS_PLAN_CODE_KIND , (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_KIND = 'WBSCODE' AND CODE_ID = I.WBS_PLAN_CODE_KIND) AS WBS_PLAN_CODE_KIND_NM , I.WBS_PLAN_CODE_ID , (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = I.WBS_PLAN_CODE_ID) AS WBS_PLAN_CODE_ID_NM , I.WBS_PLAN_NO , I.WBS_RSLTS_NO , CASE WHEN I.WBS_RSLTS_NO IS NOT NULL THEN '실적' ELSE '계획' END AS GUBUN , DECODE(I.REQ_NO, NULL, I.ACT_ID, '', I.ACT_ID, QM.ORDRG_ID) AS ACT_ID , (SELECT NAME FROM TB_CM06M01 WHERE ID = DECODE(I.REQ_NO, NULL, I.ACT_ID, '', I.ACT_ID, QM.ORDRG_ID)) AS ACT_NM , I.REQ_NO , QM.REQ_ST , (SELECT FN_CM05M01_CD_TO_NM(QM.REQ_ST) FROM DUAL) AS REQ_ST_NM , QP.RSLT_NO , TO_CHAR(I.CREAT_DTTM, 'YYYY-MM-DD') AS CREAT_DT , TO_CHAR(ACT.ACTE_DT, 'YYYY-MM-DD') AS ACTE_DT , ACT.ACT_CNTS FROM TARGET_ORDRS T JOIN TB_CR02D02 D ON D.CO_CD = T.CO_CD AND D.ORDRS_NO = T.ORDRS_NO JOIN TB_WB24M02 I ON I.CO_CD = D.CO_CD AND I.SALES_CD = D.SALES_CD LEFT OUTER JOIN TB_WB24M03 ACT ON ACT.ISS_NO = I.ISS_NO LEFT OUTER JOIN TB_QM01M01 QM ON QM.REQ_NO = I.REQ_NO LEFT OUTER JOIN TB_QM01P01 QP ON QP.REQ_NO = I.REQ_NO WHERE 1 = 1
AND I.SALES_CD = #{salesCd}
ORDER BY T.ORDRS_NO DESC, I.SALES_CD, I.WBS_PLAN_CODE_KIND, I.ISS_NO DESC
